<?php
declare(strict_types=1);
require __DIR__.'/mailbox-recovery-support.php';
final class MailboxTestTransport implements SoSecurity\Account\MailTransport {public $messages=[];public $calls=0;public function name():string{return 'owned-mailbox-relay';}public function send(SoSecurity\Account\MailMessage $message,int $milliseconds,callable $gate):SoSecurity\Account\MailResult {++$this->calls;if($gate()!==true){throw new RuntimeException('Current gate refused.');}$this->messages[]=$message;return new SoSecurity\Account\MailResult('accepted','smtp.accepted');}}
function mailboxTemplates(bool $extended=true):SoSecurity\Account\MailTemplates {$urls=[];foreach(['verify_registration','verify_address_old','verify_address_new','cancel_change','recover_account'] as $type){$urls[$type]='https://account.example.test/'.$type;}if($extended){$urls['recover_address']='https://account.example.test/recover_address';}return new SoSecurity\Account\MailTemplates('account-test',new SoSecurity\Account\Address('security@example.test'),$urls);}
function mailboxBudget(MailboxEnvironment $m):SoSecurity\Account\SendBudgets {$p=[];foreach(['site','transport','target','subject'] as $name){$p[$name]=new SoSecurity\RateLimit\BudgetPolicy('fixed_window',1000,60);}return new SoSecurity\Account\SendBudgets(new SoSecurity\Storage\FileStore($m->e->directory.'/budgets','mailbox-send',$m->e->clock,5000),'account-test',str_repeat('s',32),$p,$m->e->clock);}
mailboxCase(static function(MailboxEnvironment $m):void{$d=$m->begin();$t=new MailboxTestTransport();$budget=mailboxBudget($m);$queries=$m->e->pdo->queries;$calls=0;$guard=static function()use(&$calls):bool{++$calls;return true;};Check::throws(SoSecurity\Exception\ConfigurationException::class,static function()use($m,$budget,$t,$guard):void{$m->service->dispatcher('worker',$budget,mailboxTemplates(false),$t,$guard);});Check::same($queries,$m->e->pdo->queries);Check::same(0,$calls);Check::same(0,$t->calls);
    $sender=$m->service->dispatcher('worker',$budget,mailboxTemplates(),$t,$guard);Check::same($queries,$m->e->pdo->queries);Check::same(0,$calls);Check::same('submitted',$sender->sendNext()['state']);Check::same('submitted',$sender->sendNext()['state']);Check::same('idle',$sender->sendNext()['state']);Check::same(['owner@example.com','rescued@example.com'],array_map(static function($message):string{return $message->recipient()->value();},$t->messages));Check::same(true,$m->confirm($d));Check::same('submitted',$sender->sendNext()['state']);Check::same('submitted',$sender->sendNext()['state']);Check::same('idle',$sender->sendNext()['state']);Check::same(4,$t->calls);
});
